nt:space-between;gap:10px;color:#475569;font-size:11px;font-weight:800}.ed-track{height:8px;margin-top:6px;border-radius:999px;background:#edf1f6;overflow:hidden}.ed-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#172348,#5269aa)}.ed-note{margin-top:16px;border-left:4px solid #fabd02;border-radius:10px;background:#fff9e8;padding:13px;color:#66520c;font-size:12px}.ed-export{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.ed-export a{border:1px solid #dce4ef;border-radius:9px;padding:9px 12px;color:#334155;font-size:11px;font-weight:850;text-decoration:none}@media(max-width:1000px){.ed-kpis{grid-template-columns:repeat(2,1fr)}.ed-grid{grid-template-columns:1fr}}@media(max-width:600px){.ed-kpis,.ed-actions{grid-template-columns:1fr}}
