    <?php if($moduleKey==='clients'): ?><div class="ed-client-shortcut"><a href="<?=$root('clients/liste.php')?>"><i class="fa-solid fa-chart-line"></i> Consulter les détails clients</a></div><?php endif; ?>
    <?php if($moduleKey==='chantiers'):?><form class="ed-scope" method="get"><input type="hidden" name="view" value="<?=htmlspecialchars($view)?>"><p><strong>Périmètre des indicateurs :</strong> <?=$includeArchived?'tous les chantiers, archives comprises':'chantiers actifs uniquement'?>.</p><label><input type="checkbox" name="include_archived" value="1" <?=$includeArchived?'checked':''?> onchange="this.form.submit()"> Inclure les chantiers archivés</label></form><?php endif; ?>
    <section class="ed-kpis"><?php foreach($data['kpis'] as $kpi):?><article class="ed-kpi"><span><?=htmlspecialchars($kpi['label'])?></span><strong><?=htmlspecialchars($kpi['value'])?></strong><small><?=htmlspecialchars($kpi['note'])?></small></article><?php endforeach;?></section>
    <?php if($view==='dashboard'):?><section class="ed-grid"><article class="ed-panel"><h2>Accès rapides</h2><p>Les actions essentielles sont accessibles sans mélanger création et consultation.</p><div class="ed-actions"><a class="primary" href="<?=$root($create)?>"><i class="fa-solid fa-plus"></i>Nouvelle saisie</a><a href="<?=$root($list)?>"><i class="fa-solid fa-list"></i>Ouvrir le listing</a><?php if($moduleKey==='clients'):?><a href="<?=$root('clients/details.php?id='.(int)($data['recent'][0]['id']??0))?>"><i class="fa-solid fa-chart-line"></i>Récapitulatif activité</a><?php endif;?><a href="<?=$root($moduleKey.'/parametrage.php')?>"><i class="fa-solid fa-sliders"></i>Paramétrage</a><?php if($moduleKey==='chantiers'):?><a href="<?=$root('chantiers/regularisation.php')?>"><i class="fa-solid fa-screwdriver-wrench"></i>Régularisation</a><?php endif;?></div><div class="ed-export"><a href="<?=$root('exports/finea_module_export.php?module='.$moduleKey.'&format=pdf'.($includeArchived?'&include_archived=1':''))?>"><i class="fa-solid fa-file-pdf"></i> Export PDF</a><a href="<?=$root('exports/finea_module_export.php?module='.$moduleKey.'&format=xlsx'.($includeArchived?'&include_archived=1':''))?>"><i class="fa-solid fa-file-excel"></i> Export Excel</a></div></article><article class="ed-panel"><h2>Éléments récents</h2><p>Dernières informations enregistrées dans ce module.</p><div class="ed-list"><?php foreach($data['recent'] as $item):?><div class="ed-list-item"><div><strong><?=htmlspecialchars((string)($item['label']??''),ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars((string)($item['meta']??''),ENT_QUOTES,'UTF-8')?></small></div><?php if($moduleKey==='clients'&&!empty($item['id'])):?><a class="ed-pill" href="<?=$root('clients/details.php?id='.(int)$item['id'])?>">Détails</a><?php else:?><span class="ed-pill"><?=htmlspecialchars((string)($item['badge']??''),ENT_QUOTES,'UTF-8')?></span><?php endif;?></div><?php endforeach;?><?php if(!$data['recent']):?><p>Aucune donnée disponible.</p><?php endif;?></div></article></section>
    <?php elseif($view==='statistics'):?><?php if($moduleKey==='clients'): $finance=$data['finance'];$moneyValue=static fn(float $value):string=>number_format($value,0,',',' ').' FCFA';$maxRevenue=max(1,...array_map(static fn(array $row)=>(float)$row['invoiced'],$finance['top']));$maxMonth=max(1,...array_map(static fn(array $row)=>(float)$row['value'],$finance['monthly']));?><section class="ed-kpis"><article class="ed-kpi"><span>CA facturé</span><strong><?=$moneyValue((float)$finance['invoiced'])?></strong><small>Total des factures clients</small></article><article class="ed-kpi"><span>Encaissé</span><strong><?=$moneyValue((float)$finance['collected'])?></strong><small>Paiements enregistrés</small></article><article class="ed-kpi"><span>Encours global</span><strong><?=$moneyValue((float)$finance['outstanding'])?></strong><small>Reste à recouvrer</small></article><article class="ed-kpi"><span>Factures</span><strong><?=number_format((int)$finance['invoice_count'],0,',',' ')?></strong><small>Factures rattachées</small></article></section><section class="ed-grid"><article class="ed-panel"><h2>Top clients par chiffre d’affaires</h2><p>Classement des clients sur les montants facturés.</p><div class="ed-bars"><?php foreach($finance['top'] as $row):?><div><div class="ed-bar-head"><span><?=htmlspecialchars((string)$row['nom_client'])?></span><strong><?=$moneyValue((float)$row['invoiced'])?></strong></div><div class="ed-track"><div class="ed-fill" style="width:<?=min(100,(float)$row['invoiced']/$maxRevenue*100)?>%"></div></div><small><?=number_format((int)$row['invoice_count'],0,',',' ')?> facture(s) · encaissé <?=$moneyValue((float)$row['collected'])?></small></div><?php endforeach;?><?php if(!$finance['top']):?><p>Aucune donnée de facturation disponible.</p><?php endif;?></div></article><article class="ed-panel"><h2>Fréquence de facturation</h2><p>Montants et volume des factures sur les douze derniers mois.</p><div class="ed-bars"><?php foreach($finance['monthly'] as $month):?><div><div class="ed-bar-head"><span><?=htmlspecialchars((string)$month['label'])?></span><strong><?=$moneyValue((float)$month['value'])?></strong></div><div class="ed-track"><div class="ed-fill" style="width:<?=min(100,(float)$month['value']/$maxMonth*100)?>%"></div></div><small><?=number_format((int)$month['invoice_count'],0,',',' ')?> facture(s)</small></div><?php endforeach;?><?php if(!$finance['monthly']):?><p>Aucune facture sur la période.</p><?php endif;?></div></article></section><?php else:?><section class="ed-grid"><article class="ed-panel"><h2>Répartition principale</h2><p>Lecture quantitative des données actuellement disponibles.</p><div class="ed-bars"><?php $max=max(1,...array_column($data['distribution'],'value'));foreach($data['distribution'] as $bar):?><div><div class="ed-bar-head"><span><?=htmlspecialchars($bar['label'])?></span><strong><?=number_format((float)$bar['value'],0,',',' ')?></strong></div><div class="ed-track"><div class="ed-fill" style="width:<?=min(100,(float)$bar['value']/$max*100)?>%"></div></div></div><?php endforeach;?></div></article><article class="ed-panel"><h2>Lecture rapide</h2><p><?=htmlspecialchars($data['analysis'])?></p><div class="ed-note">Les indicateurs Chantier excluent systématiquement les chantiers archivés.</div></article></section><?php endif;?>
    <?php else:?><section class="ed-grid"><article class="ed-panel"><h2>Analyse décisionnelle</h2><p><?=htmlspecialchars($data['analysis'])?></p><div class="ed-bars"><?php $max=max(1,...array_column($data['distribution'],'value'));foreach(array_slice($data['distribution'],0,8) as $bar):?><div><div class="ed-bar-head"><span><?=htmlspecialchars($bar['label'])?></span><strong><?=number_format((float)$bar['value'],0,',',' ')?></strong></div><div class="ed-track"><div class="ed-fill" style="width:<?=min(100,(float)$bar['value']/$max*100)?>%"></div></div></div><?php endforeach;?></div></article><article class="ed-panel"><h2>Action recommandée</h2><p><?=htmlspecialchars($data['recommendation'])?></p><div class="ed-actions"><a class="primary" href="<?=$root($list)?>"><i class="fa-solid fa-arrow-right"></i>Examiner les données</a></div></article></section><?php endif;?>
    <?php $content=ob_get_clean();require __DIR__.'/module_layout.php';
}

function finea_entity_dashboard_data(PDO $pdo,string $module,bool $includeArchived=false):array
{
    $money=static fn(float $v):string=>number_format($v,0,',',' ').' FCFA';
    if($module==='clients'){
        $total=(int)$pdo->query('SELECT COUNT(*) FROM client_banamur')->fetchColumn();$active=(int)$pdo->query('SELECT COUNT(DISTINCT client_id) FROM chantier_banamur WHERE archived_at IS NULL')->fetchColumn();$quoted=(int)$pdo->query('SELECT COUNT(DISTINCT client_id) FROM devis_banamur')->fetchColumn();$new=(int)$pdo->query('SELECT COUNT(*) FROM client_banamur WHERE date_creat_client>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)')->fetchColumn();
        $dist=$pdo->query("SELECT COALESCE(NULLIF(TRIM(pays_client),''),'Non renseigné') label,COUNT(*) value FROM client_banamur GROUP BY label ORDER BY value DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC)?:[];$recent=$pdo->query("SELECT id_client id,nom_client label,CONCAT(COALESCE(code_client,'Sans code'),' · ',COALESCE(pays_client,'Pays non renseigné')) meta,DATE_FORMAT(date_creat_client,'%d/%m/%Y') badge FROM client_banamur ORDER BY id_client DESC LIMIT 6")->fetchAll(PDO::FETCH_ASSOC)?:[];
        $finance=['invoiced'=>0.0,'collected'=>0.0,'outstanding'=>0.0,'invoice_count'=>0,'top'=>[],'monthly'=>[]];
        try{$rows=$pdo->query("SELECT cl.id_client,cl.nom_client,COUNT(fv.id_facture_vente) invoice_count,COALESCE(SUM(fv.total_ttc),0) invoiced,COALESCE(SUM(CASE WHEN fv.paiement_statut='payee' THEN COALESCE(NULLIF(fv.collected_amount,0),fv.total_ttc) ELSE 0 END),0) collected FROM client_banamur cl LEFT JOIN facture_vente_banamur fv ON fv.client_id=cl.id_client OR fv.chantier_id IN (SELECT c2.id FROM chantier_banamur c2 WHERE c2.client_id=cl.id_client) GROUP BY cl.id_client,cl.nom_client ORDER BY invoiced DESC")->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($rows as $row){$finance['invoiced']+=(float)$row['invoiced'];$finance['collected']+=(float)$row['collected'];$finance['invoice_count']+=(int)$row['invoice_count'];}$finance['outstanding']=max(0,$finance['invoiced']-$finance['collected']);$finance['top']=array_slice($rows,0,8);$finance['monthly']=$pdo->query("SELECT DATE_FORMAT(COALESCE(invoice_date,DATE(created_at)),'%Y-%m') label,COUNT(*) invoice_count,COALESCE(SUM(total_ttc),0) value FROM facture_vente_banamur WHERE COALESCE(invoice_date,DATE(created_at))>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY label ORDER BY label")->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $ignored){}
        return['kpis'=>[['label'=>'Clients enregistrés','value'=>(string)$total,'note'=>'Base commerciale complète'],['label'=>'Avec chantier actif','value'=>(string)$active,'note'=>'Clients actuellement en production'],['label'=>'Avec devis','value'=>(string)$quoted,'note'=>'Clients ayant reçu une proposition'],['label'=>'Nouveaux · 30 jours','value'=>(string)$new,'note'=>'Dynamique commerciale récente']],'distribution'=>$dist,'recent'=>$recent,'finance'=>$finance,'analysis'=>$active.' client(s) possèdent au moins un chantier actif sur '.$total.' clients enregistrés.','recommendation'=>'Compléter les coordonnées des clients actifs et examiner les clients sans devis ni chantier récent.'];
    }
    if($module==='unites'){
        $total=(int)$pdo->query('SELECT COUNT(*) FROM unites_mesure')->fetchColumn();$used=(int)$pdo->query('SELECT COUNT(DISTINCT unite_id) FROM ligne_devis_banamur WHERE unite_id IS NOT NULL')->fetchColumn();$lines=(int)$pdo->query('SELECT COUNT(*) FROM ligne_devis_banamur WHERE unite_id IS NOT NULL')->fetchColumn();$unused=max(0,$total-$used);$dist=$pdo->query('SELECT CONCAT(u.libelle," (",u.symbole,")") label,COUNT(l.id) value FROM unites_mesure u LEFT JOIN ligne_devis_banamur l ON l.unite_id=u.id GROUP BY u.id,u.libelle,u.symbole ORDER BY value DESC,u.libelle LIMIT 12')->fetchAll(PDO::FETCH_ASSOC)?:[];$recent=$pdo->query("SELECT libelle label,CONCAT('Symbole : ',symbole) meta,CONCAT('#',id) badge FROM unites_mesure ORDER BY id DESC LIMIT 6")->fetchAll(PDO::FETCH_ASSOC)?:[];
        return['kpis'=>[['label'=>'Unités disponibles','value'=>(string)$total,'note'=>'Référentiel de mesure'],['label'=>'Unités utilisées','value'=>(string)$used,'note'=>'Présentes dans au moins un devis'],['label'=>'Lignes rattachées','value'=>(string)$lines,'note'=>'Volume d’utilisation'],['label'=>'Unités inutilisées','value'=>(string)$unused,'note'=>'À vérifier ou rationaliser']],'distribution'=>$dist,'recent'=>$recent,'analysis'=>$used.' unité(s) sont effectivement utilisées sur '.$total.' disponibles.','recommendation'=>'Vérifier les unités jamais utilisées et fusionner les symboles redondants avant leur diffusion dans les devis.'];
    }
    $scope=$includeArchived?'1=1':'archived_at IS NULL';
    $qualifiedScope=$includeArchived?'1=1':'c.archived_at IS NULL';
    $scopeLabel=$includeArchived?'tous les chantiers':'les chantiers actifs';
    $total=(int)$pdo->query('SELECT COUNT(*) FROM chantier_banamur WHERE '.$scope)->fetchColumn();$compliant=(int)$pdo->query("SELECT COUNT(*) FROM chantier_banamur WHERE ".$scope." AND financial_data_status='compliant'")->fetchColumn();$contract=(float)$pdo->query('SELECT COALESCE(SUM(d.total_ttc),0) FROM chantier_banamur c JOIN devis_banamur d ON d.id=c.devis_id WHERE '.$qualifiedScope)->fetchColumn();$debit=(float)$pdo->query('SELECT COALESCE(SUM(db.montant_debourse),0) FROM chantier_banamur c JOIN debourse_banamur db ON db.devis_id=c.devis_id WHERE '.$qualifiedScope)->fetchColumn();$dist=$pdo->query("SELECT COALESCE(NULLIF(cl.nom_client,''),'Client non renseigné') label,COUNT(c.id) value FROM chantier_banamur c LEFT JOIN client_banamur cl ON cl.id_client=c.client_id WHERE $qualifiedScope GROUP BY cl.id_client,cl.nom_client ORDER BY value DESC LIMIT 12")->fetchAll(PDO::FETCH_ASSOC)?:[];$recent=$pdo->query("SELECT c.titre label,CONCAT(c.code,' · ',COALESCE(cl.nom_client,'Client non renseigné'),IF(c.archived_at IS NULL,'',' · Archivé')) meta,DATE_FORMAT(c.date_creation,'%d/%m/%Y') badge FROM chantier_banamur c LEFT JOIN client_banamur cl ON cl.id_client=c.client_id WHERE $qualifiedScope ORDER BY c.id DESC LIMIT 6")->fetchAll(PDO::FETCH_ASSOC)?:[];
    return['kpis'=>[['label'=>$includeArchived?'Tous les chantiers':'Chantiers actifs','value'=>(string)$total,'note'=>$includeArchived?'Archives incluses sur demande':'Archives exclues par défaut'],['label'=>'Dossiers conformes','value'=>(string)$compliant,'note'=>'Devis, planning, déboursé et facturation'],['label'=>'Montant contractuel','value'=>$money($contract),'note'=>'Total TTC de '.$scopeLabel],['label'=>'Déboursés prévus','value'=>$money($debit),'note'=>'Engagement budgétaire de '.$scopeLabel]],'distribution'=>$dist,'recent'=>$recent,'analysis'=>$compliant.' dossier(s) conforme(s) sur '.$total.' pour '.$scopeLabel.'.','recommendation'=>$includeArchived?'Cette vue historique inclut les archives. Décochez l’option pour revenir au pilotage opérationnel actif.':'Traiter en priorité les dossiers actifs signalés dans la régularisation afin de fiabiliser trésorerie, marge et facturation.'];
}
